function UserProfile({ name, email, avatar }) {
  return (
    <div className="user-profile">
      <img src={avatar} alt={`${name}'s avatar`} className="avatar" />
      <div className="user-info">
        <h3>{name}</h3>
        <p>{email}</p>
      </div>
    </div>
  );
}

function BadgeList({ badges }) {
  if (!badges || badges.length === 0) {
    return <p className="no-badges">No badges earned yet</p>;
  }

  return (
    <div className="badge-list">
      {badges.map((badge) => (
        <span key={badge.id} className={`badge badge-${badge.type}`}>
          {badge.name}
        </span>
      ))}
    </div>
  );
}

function StatusIndicator({ status }) {
  const colors = { online: "#22c55e", away: "#eab308", offline: "#6b7280" };
  const labels = { online: "Online", away: "Away", offline: "Offline" };

  return (
    <div className="status-indicator">
      <span
        className="status-dot"
        style={{ backgroundColor: colors[status] || colors.offline }}
      />
      <span>{labels[status] || "Offline"}</span>
    </div>
  );
}

function UserCard({ user }) {
  return (
    <div className="user-card">
      <UserProfile name={user.name} email={user.email} avatar={user.avatar} />
      <StatusIndicator status={user.status} />
      <BadgeList badges={user.badges} />
    </div>
  );
}
